select public.prepify_load_bank('Chemistry', 5, $j$[["What is the primary driving force for atoms to form chemical bonds?",["To increase their total energy.","To become radioactive.","To achieve a stable noble gas electronic configuration.","To increase the number of protons."],"C",3,0,"74a0366eda77",0],["An atom forms three covalent bonds. It most likely needs:",["Three electrons for stability","Two electrons for stability","One electron for stability","Four electrons for stability"],"A",3,0,"61d6c77c6e09",0],["Which statement best explains the formation of ionic compounds?",["Like charges attract each other","Oppositely charged ions attract each other","Neutrons attract electrons","Protons are exchanged"],"B",3,0,"6108496c5788",0],["Which rule states that atoms tend to gain, lose, or share electrons to have eight electrons in their valence shell?",["Pauli exclusion principle","Duplet rule","Hund’s rule","Octet rule"],"D",3,0,"b7ab9e0afc93",0],["Which of the following is a characteristic property of ionic compounds?",["Low melting points.","High electrical conductivity in the solid state.","High melting points and brittleness.","Solubility only in organic solvents."],"C",3,0,"91279ee2f9d0",0],["Which type of bond is responsible for the high electrical and thermal conductivity of metals?",["Covalent bond.","Metallic bond","Hydrogen bond.","Ionic bond."],"B",3,0,"dd2a1b6ad7ab",0],["What determines the strength of an ionic bond?",["The number of neutrons.","The color of the crystal.","The magnitude of the charges on the ions and the distance between them.","The atomic mass of the elements."],"C",3,0,"b72a9bcd0ec5",0],["In the formation of a covalent bond, what happens to the energy of the system?",["It disappears.","It remains unchanged.","It increases.","It decreases to reach a stable energy minimum."],"D",3,0,"9259b9fa56be",0],["Electropositive elements are typically:",["Metals","Noble gases","Non-metals.","Metalloids"],"A",3,0,"3f0e2e3a6f91",0],["Which substance would have the highest melting point?",["CH₄","NaCl","H₂O","O₂"],"B",3,0,"4cfa2d345abb",0],["Covalent compounds usually have:",["A rigid lattice structure.","Ionic conductivity.","High boiling points.","Low boiling points due to weak intermolecular forces between molecules."],"D",3,0,"da337f7ab047",0],["Atoms with high electronegativity are more likely to form:",["Cations.","Metallic bonds.","Anions.","Nothing."],"C",3,0,"8d83b7ef4865",0],["In the formation of MgO, what charge do the ions acquire?",["+1, -1","+2, -2","+1, -2","0, 0"],"B",3,0,"7ecd757c1eb9",0],["What represents the \"cloud\" in metallic bonding?",["The neutrons.","The empty orbitals.","The protons.","The valence electrons that are no longer associated with a single nucleus."],"D",3,0,"a7a5abc748fb",0],["Why is it that covalent bonds are generally strong?",["Because shared electrons are held tightly by two positively charged nuclei.","Because they involve transfer.","Because they are large.","Because they only occur in solids."],"A",3,0,"fca229843def",0],["Which of the following substances would conduct electricity as a solid?",["NaCl","Copper","Diamond","H₂O"],"B",3,0,"bc3218a1f372",0],["Why is fluorine highly reactive?",["It has no valence electrons","It easily loses seven electrons","It has a complete octet","It needs one electron to complete its octet"],"D",3,0,"f4f1ba75a65f",0],["Why is electron transfer unlikely between two oxygen atoms?",["Both atoms tend to gain electrons rather than lose them","Oxygen has no valence electrons","Oxygen atoms are metals","Oxygen atoms already have complete octets"],"A",3,0,"8c362c283451",0],["A student says, “Every bond involves electron transfer.” Which substance proves the statement incorrect?",["NaCl","MgO","H₂O","KCl"],"C",3,1,"a4b20da7c9ba",0],["Why does hydrogen form one covalent bond, but oxygen usually forms two?",["Oxygen is heavier than hydrogen","Hydrogen needs one electron, and oxygen needs two electrons for stability","Oxygen has fewer electrons","Hydrogen forms only ionic bonds"],"B",3,0,"536db92cc178",0],["Why does the melting point of magnesium oxide (MgO) significantly exceed that of sodium chloride (NaCl)?",["The lattice energy of MgO is much higher due to the greater electrostatic attraction between +2/-2 ions compared to +1/-1 ions.","MgO is a covalent compound.","NaCl is a metal.","Mg and O are smaller than Na and Cl."],"A",3,0,"d7f45cfc8339",0],["In the molecule BF₃, the Boron atom is said to be \"electron-deficient.\" What does this mean?",["It has 8 valence electrons.","It has only 6 valence electrons, meaning it does not satisfy the octet rule.","It has 10 valence electrons.","It is a metal."],"B",3,0,"2d4baa6b00b3",0],["When an atom forms a covalent bond, what is happening to the atomic orbitals?",["They expand to infinite size.","They are destroyed.","They become ionic.","They overlap to create a region of space where electrons are likely to be shared."],"D",3,0,"8c19d73fcd23",0],["Which of these is a non-directional force?",["The covalent bond between C and H.","The metallic bond between Na atoms.","The electrostatic attraction in an ionic lattice.","Both B and C."],"D",3,0,"b4ab0e483eed",0],["What happens to the electronegativity difference as you go from an ionic to a covalent bond?",["It becomes negative.","It increases.","It stays the same.","It decreases."],"D",3,0,"43d866ec4bfa",0],["An atom X loses one electron while atom Y gains one electron. Which statement is correct?",["Both become negatively charged","X becomes a cation, and Y becomes an anion","Both become positively charged","X becomes an anion, and Y becomes a cation"],"B",3,0,"f6a07233a9e9",0],["You are given an unknown substance X. It has a very high melting point, is brittle, and does not conduct electricity as a solid. When you dissolve it in water, the solution conducts electricity vigorously. What is the nature of X?",["Polar covalent molecule","Metallic solid","Covalent network solid","Ionic lattice"],"D",3,0,"5ac5eeed921a",0],["A scientist discovers a material that conducts electricity in both the solid and liquid states and is highly malleable. What type of bonding is present?",["Covalent","Metallic","Ionic","Dative"],"B",3,1,"7e5a2650cc7c",0],["A student compares NaCl and Cl₂. Both contain chlorine atoms. Why is chlorine present as ions in one substance but as molecules in the other?",["Chlorine changes its atomic number","The bonding partner is different","Chlorine gains protons in NaCl","Chlorine loses neutrons in Cl₂"],"B",3,1,"914c7bf30e2c",0],["A metal atom loses two electrons while a non-metal atom gains two electrons. What is the ratio of ions in the resulting compound?",["1 : 1","1 : 2","2 : 1","2 : 3"],"A",3,0,"93fc29a0ecaf",0],["You have two liquids: H₂O and CCl₄. You notice that NaCl dissolves in H₂O but not in CCl₄. Why?",["CCl₄ is too viscous.","NaCl is covalent.","H₂O is polar and interacts with ions; CCl₄ is non-polar and cannot stabilize ions.","H₂O is a metal."],"C",3,0,"af5fd09a30ac",0],["An atom Z has an empty 2p orbital and forms a bond with NH₃, where both electrons are provided by the Nitrogen. What is this bond called?",["Coordinate covalent bond","Ionic bond","Metallic bond","Hydrogen bond"],"A",3,0,"aeaf06fcf0f4",0],["You add a substance to a beaker of water; the substance sinks and does not dissolve, and it does not conduct electricity. What kind of substance is it likely to be?",["A salt","An ionic compound","A metal","A simple covalent molecule"],"D",3,0,"1763e04e108e",0],["A scientist labels a bond as \"non-directional.\" Which type of bonding could this be?",["Ionic or Metallic.","Covalent only.","Only metallic.","Only ionic."],"A",3,1,"ad3d60c57519",0],["Why do ionic crystals shatter when struck by a hammer?",["They become covalent.","The layers slide, and like-charged ions end up adjacent to each other, causing massive repulsion.","The electrons escape.","The metal atoms bend."],"B",3,0,"df36ac2c19e0",0],["Why can't a simple covalent molecule like CH₄ conduct electricity?",["It has no ions and no delocalized electrons.","It is too small.","It has no protons.","It is metallic."],"A",3,0,"1bd02de2241a",0],["If an atom of Magnesium reacts with Chlorine, what happens to the energy level?",["Energy remains constant.","The atom disappears.","Energy is absorbed.","Energy is released as the system reaches a more stable configuration."],"D",3,1,"0328a33f08c9",0],["Why are ionic compounds solids at room temperature?",["They have weak bonds.","The electrostatic forces between ions are so strong that they lock them into a rigid, repeating lattice.","They are metals.","They have no bonds."],"B",3,0,"d2eaea25553a",0],["You find a substance that is a \"giant\" structure, very hard, and does not conduct electricity. What could it be?",["Graphite","Sodium Chloride","Silicon Dioxide","Copper"],"C",3,0,"74d4f804d78a",0],["Why are delocalized electrons in metals considered \"delocalized\"?",["They are not bound to any single atom and can move throughout the lattice.","They are lost.","They are in the nucleus.","They are in the inner shell."],"A",3,0,"4f3cd043e374",0],["An atom with six valence electrons reacts with hydrogen atoms. How many covalent bonds will it most likely form?",["One","Two","Three","Four"],"B",3,0,"894b8d38263b",0],["A student notices that an ionic compound remains electrically neutral despite containing charged particles. Why?",["Positive and negative charges balance each other","Electrons disappear during bonding","Only positive ions are present","Only negative ions are present"],"A",3,1,"2cdf433508a2",0],["A student argues that atoms bond because they want to increase their mass. Which observation best refutes this idea?",["Bonding increases neutrons","Bonding creates new elements","Bonding increases the atomic number","Bonding changes electron arrangement, not nuclear composition"],"D",3,1,"f83de9f9942f",0],["An atom contributes both electrons in a shared pair while the other contributes none. Before bond formation, the second atom most likely had:",["No valence electrons","A vacant orbital available for the pair","Excess neutrons","A positive nucleus only"],"B",3,0,"3632f5579bb0",0],["A student observes that chlorine forms Cl⁻ rather than Cl⁺ during ionic bond formation. The most reasonable explanation is that chlorine:",["Easily loses seven electrons","Is a metal","Has one valence electron","Needs one electron for stability"],"D",3,1,"528ed64e81af",0],["An atom gains electrons during bond formation. Which quantity remains unchanged?",["Electronic configuration","Atomic number","Charge","Number of electrons"],"B",3,0,"93c7d8231a37",0],["Element P has 2 valence electrons, and Element Q has 7 valence electrons. If they react, what is the most likely formula and bond type?",["PQ₂, Covalent","P₂Q, Ionic","PQ₂, Ionic","PQ₇, Metallic"],"C",3,0,"86cff65a999f",0],["Why does the bond angle in NH₃ (107o) differ from the ideal tetrahedral angle (109.5o)?",["The lone pair on Nitrogen exerts more repulsion on the bonding pairs than the bonding pairs do on each other.","NH₃ is an ionic compound.","Nitrogen has too many protons.","H atoms are too large."],"A",3,0,"c96fc33c307d",0],["Which of the following explains why NH₃ has a higher boiling point than PH₃?",["NH₃ has stronger Van der Waals forces.","Nitrogen is more electronegative than Phosphorus, allowing NH₃ to form intermolecular Hydrogen bonds, while PH₃ cannot.","NH₃ is a larger molecule.","PH₃is ionic."],"B",3,0,"10665581ffa0",0],["In the molecule SF₆, the Sulfur atom is said to have an \"expanded octet.\" How is this physically possible?",["It is an ionic compound.","It has no bonds.","Sulfur uses its vacant 3d orbitals to accommodate more than 8 valence electrons.","It loses its nucleus."],"C",3,0,"d89348e42ae7",0],["Which factor is the most significant in determining the \"covalent character\" of an ionic bond?",["High charge and small size of the cation.","Large size of the cation.","Low electronegativity of the anion.","The color of the crystal."],"A",3,0,"3f3364c33bca",0],["Which of the following bonds is the most polar?",["C-H","C-F","C-O","C-N"],"B",3,0,"37aefda6494f",0],["Why is the bond energy of O₂ (double bond) not exactly twice the bond energy of O-O (single bond)?",["Double bonds are always exactly double.","O₂ is ionic.","It depends on the color.","π-bonds are generally weaker than σ-bonds due to less effective orbital overlap, so they do not add linearly."],"D",3,0,"b13b840901bf",0],["Which of the following ions is most likely to show the highest degree of polarization in a bond?",["Na⁺","Al³⁺","K⁺","Ca²⁺"],"B",3,0,"b8b344a6b208",0],["If electrons in a metallic bond were localized between specific atoms, metals would most likely lose their:",["Color","Malleability","Atomic mass","Density"],"B",3,0,"b950aa602235",0],["In an ionic crystal, each ion is surrounded by ions of opposite charge. This arrangement primarily serves to:",["Reduce atomic number.","Increase neutron count.","Maximize electrostatic stability.","Form molecules."],"C",3,0,"05f8c54966dc",0],["In the ammonium ion, NH₃ donates both electrons of a bond to H⁺. This bond is a:",["coordinate covalent bond","ionic bond","metallic bond","hydrogen bond"],"A",3,0,"aeaf06fcf0f4",0],["Atoms tend to gain, lose or share electrons so that their outer shell holds eight electrons. This is the:",["duplet rule","octet rule","Hund's rule","Aufbau rule"],"B",1,0,"b7ab9e0afc93",0],["Which substance conducts electricity in the solid state?",["Sugar","Aluminium","Sulphur","Ice"],"B",3,0,"bc3218a1f372",0],["Element X has 1 valence electron and element Y has 6. The compound they form is most likely:",["XY₂, covalent","X₂Y, ionic","XY, covalent","XY₆, ionic"],"B",5,0,"86cff65a999f",0],["Which bond is the most polar?",["H–H","H–Cl","H–F","Cl–Cl"],"C",5,0,"37aefda6494f",0],["A white solid has a high melting point, does not conduct as a solid, but conducts when dissolved in water. It is most likely:",["an ionic compound","a metal","a covalent gas","graphite"],"A",3,1,"5ac5eeed921a",0],["Nitrogen usually forms three covalent bonds because it:",["needs three more electrons to complete its octet","has three shells","is a metal","has no valence electrons"],"A",3,0,"536db92cc178",0],["A covalent bond forms when the orbitals of two atoms:",["overlap and share a pair of electrons","move apart","transfer all electrons","become ions"],"A",3,0,"8c19d73fcd23",0],["The formula of the compound formed between sodium ions (Na⁺) and fluoride ions (F⁻) is:",["Na₂F₃","Na₃F₂","NaF","Na₂F"],"C",3,0,"gen-chemistry-c5-ionic-formula",0],["The formula of the compound formed between potassium ions (K⁺) and nitride ions (N³⁻) is:",["KN₃","K₃N","KN","K₂N₃"],"B",3,0,"gen-chemistry-c5-ionic-formula",0],["The formula of the compound formed between aluminium ions (Al³⁺) and oxide ions (O²⁻) is:",["Al₃O₂","Al₂O₃","AlO","Al₂O"],"B",3,0,"gen-chemistry-c5-ionic-formula",0],["The formula of the compound formed between magnesium ions (Mg²⁺) and nitride ions (N³⁻) is:",["MgN","Mg₃N₂","Mg₂N₃","Mg₃N"],"B",3,0,"gen-chemistry-c5-ionic-formula",0],["The formula of the compound formed between magnesium ions (Mg²⁺) and oxide ions (O²⁻) is:",["Mg₂O₂","MgO","Mg₂O","MgO₂"],"B",3,0,"gen-chemistry-c5-ionic-formula",0],["The formula of the compound formed between magnesium ions (Mg²⁺) and fluoride ions (F⁻) is:",["Mg₂F","MgF","Mg₂F₃","MgF₂"],"D",3,0,"gen-chemistry-c5-ionic-formula",0],["How many shared pairs of electrons are there in a molecule of N₂?",["4","3","6","2"],"B",3,0,"gen-chemistry-c5-shared-pairs",0],["How many shared pairs of electrons are there in a molecule of CH₄?",["5","8","4","3"],"C",3,0,"gen-chemistry-c5-shared-pairs",0],["How many shared pairs of electrons are there in a molecule of CO₂?",["5","3","8","4"],"D",3,0,"gen-chemistry-c5-shared-pairs",0],["How many shared pairs of electrons are there in a molecule of HCl?",["4","3","1","2"],"C",3,0,"gen-chemistry-c5-shared-pairs",0],["How many shared pairs of electrons are there in a molecule of H₂O?",["1","2","3","4"],"B",3,0,"gen-chemistry-c5-shared-pairs",0],["How many shared pairs of electrons are there in a molecule of C₂H₄?",["12","7","5","6"],"D",3,0,"gen-chemistry-c5-shared-pairs",0]]$j$::jsonb, true);
